#!/usr/bin/env bash
# 자동기동 등록 (systemd --user Quadlet):  bin/install-quadlet.sh <앱>
#  전제: Linger=yes (인프라팀 요청) / RHEL9 podman 5.x
source "$(dirname "$0")/common.sh" "${1:-}"
[[ -n "${APP}" ]] || die "사용법: install-quadlet.sh <앱>"
image_exists "${IMAGE_NAME}:current" || die "${IMAGE_NAME}:current 없음 (먼저 deploy)"

mkdir -p "${QUADLET_DIR}"
QARGS="$(limit_args)"
podman rm -f "${APP}" >/dev/null 2>&1 || true

cat > "${QUADLET_FILE}" <<UNIT
# generated by ATMS bin/install-quadlet.sh
[Unit]
Description=ATMS ${APP}
Wants=network-online.target
After=network-online.target

[Container]
ContainerName=${APP}
Image=${IMAGE_NAME}:current
PublishPort=${HOST_PORT}:${CONTAINER_PORT}
EnvironmentFile=${APP_ENV_FILE}
Volume=${LOG_DIR}:/app/logs:Z
Volume=${CONFIG_DIR}:/app/config:ro,Z
${QARGS:+PodmanArgs=${QARGS}}

[Service]
Restart=always
RestartSec=10
TimeoutStartSec=180
TimeoutStopSec=40

[Install]
WantedBy=default.target
UNIT

log "생성: ${QUADLET_FILE}"
systemctl --user daemon-reload
systemctl --user start "${APP}.service"
systemctl --user status "${APP}.service" --no-pager | head -10
